 35 | 	value := 0
 36 | 	aces := 0
 37 | 
 38 | 	for _, card := range h.Cards {
 39 | 		if card.Rank == cards.Ace {
 40 | 			aces++
 41 | 			value += 11
 42 | 		} else {
 43 | 			value += card.Value
 44 | 		}
 45 | 	}
 46 | 
 47 | 	// Adjust for aces if value exceeds 21
 48 | 	for aces > 0 && value > 21 {
 49 | 		value -= 10 // Change ace from 11 to 1
 50 | 		aces--
 51 | 	}
 52 | 
 53 | 	return value
 54 | }
 55 | 
 56 | // IsSoft returns true if the hand contains an ace counted as 11
 57 | func (h *Hand) IsSoft() bool {
 58 | 	valueWithoutAceAdjustment := 0
 59 | 	hasAce := false
 60 | 
 61 | 	for _, card := range h.Cards {
 62 | 		if card.Rank == cards.Ace {
 63 | 			hasAce = true
 64 | 			valueWithoutAceAdjustment += 11
 65 | 		} else {
 66 | 			valueWithoutAceAdjustment += card.Value
 67 | 		}
 68 | 	}
 69 | 
 70 | 	// If the value without adjustment is <= 21 and has an ace, it's soft
 71 | 	originalValue := valueWithoutAceAdjustment
 72 | 	acesCount := 0
 73 | 	for _, card := range h.Cards {
 74 | 		if card.Rank == cards.Ace {
 75 | 			acesCount++
 76 | 		}
 77 | 	}
 78 | 
 79 | 	// Check if after ace adjustments it's still soft
 80 | 	valueWithAceAdjustment := h.Value()
 81 | 
 82 | 	// If original value <= 21 and we had to adjust aces, it's soft
 83 | 	// Or if the value is less than original due to ace adjustments
 84 | 	return hasAce && valueWithAceAdjustment <= 21 && valueWithAceAdjustment != originalValue
 85 | }
 86 | 
 87 | // CanSplit returns true if the hand can be split (same rank cards, not already split beyond max)
 88 | func (h *Hand) CanSplit(rules *RuleSet) bool {
 89 | 	if len(h.Cards) != 2 {
 90 | 		return false
 91 | 	}
 92 | 
 93 | 	// Cards must be of the same rank (or both worth 10 for face cards)
 94 | 	card1, card2 := h.Cards[0], h.Cards[1]
 95 | 
 96 | 	// If both are aces, special handling
 97 | 	if card1.Rank == cards.Ace && card2.Rank == cards.Ace {
 98 | 		if rules.SplitAcesOnceOnly {
 99 | 			return true // Can split aces once regardless of other rules
100 | 		}
101 | 		return !rules.SplitAcesOnceOnly // If not limited to one split, allow more
102 | 	}
103 | 
104 | 	// Same rank (A-A, K-K, etc.) or both 10-value cards (K-Q, J-10, etc.)
105 | 	return card1.Rank == card2.Rank || (card1.Value == card2.Value && card1.Value == 10)
106 | }
107 | 
108 | // CanDoubleDown returns true if the hand can be doubled down
109 | func (h *Hand) CanDoubleDown(rules *RuleSet) bool {
110 | 	// Typically can double down on any first two cards
111 | 	// Some games restrict to 9, 10, or 11 only
112 | 	return len(h.Cards) == 2 && !h.IsDouble
113 | }
