162 | // PlaceBet places a bet for the current player
163 | func (g *GameEngine) PlaceBet(playerID int, betAmount float64) error {
164 | 	if g.State != BettingState {
165 | 		return errors.New("cannot place bet when not in betting state")
166 | 	}
167 | 
168 | 	player := g.getPlayerByID(playerID)
169 | 	if player == nil {
170 | 		return errors.New("player not found")
171 | 	}
172 | 
173 | 	if betAmount <= 0 {
174 | 		return errors.New("bet amount must be positive")
175 | 	}
176 | 
177 | 	if player.Chips < betAmount {
178 | 		return errors.New("insufficient chips")
179 | 	}
180 | 
181 | 	player.CurrentBet = betAmount
182 | 	return nil
183 | }
