242 | // checkForBlackjacks checks if any player or the dealer has a blackjack
243 | func (g *GameEngine) checkForBlackjacks() {
244 | 	// Check dealer first
245 | 	if g.hasBlackjack(g.Dealer) {
246 | 		g.Dealer.IsBlackjack = true
247 | 	}
248 | 
249 | 	// Check each player
250 | 	for _, player := range g.Players {
251 | 		if len(player.Hands) > 0 && g.hasBlackjack(player.Hands[0]) {
252 | 			player.Hands[0].IsBlackjack = true
253 | 		}
254 | 	}
255 | }
