274 | // Hit draws a card for the current player's current hand
275 | func (g *GameEngine) Hit(playerID int) error {
276 | 	if g.State != PlayerTurnState {
277 | 		return errors.New("cannot hit when not in player turn state")
278 | 	}
279 | 
280 | 	player := g.getPlayerByID(playerID)
281 | 	if player == nil {
282 | 		return errors.New("player not found")
283 | 	}
284 | 
285 | 	currentHand := g.getCurrentHand(player)
286 | 	if currentHand == nil {
287 | 		return errors.New("no active hand found")
288 | 	}
289 | 
290 | 	card, err := g.Shoe.DrawCard()
291 | 	if err != nil {
292 | 		return err
293 | 	}
294 | 
295 | 	currentHand.Cards = append(currentHand.Cards, card)
296 | 
297 | 	// Check if the hand busted
298 | 	if currentHand.Value() > 21 {
299 | 		currentHand.IsBusted = true
300 | 		currentHand.Active = false
301 | 
302 | 		// Move to next hand or next player
303 | 		if !g.moveToNextHand() {
304 | 			g.moveToNextPlayer()
305 | 		}
306 | 	} else if g.hasBlackjack(currentHand) {
307 | 		// If the player gets a blackjack after hitting, they're done with this hand
308 | 		currentHand.Active = false
309 | 		if !g.moveToNextHand() {
310 | 			g.moveToNextPlayer()
311 | 		}
312 | 	}
313 | 
314 | 	return nil
315 | }
