343 | // DoubleDown doubles the bet and gives one more card
344 | func (g *GameEngine) DoubleDown(playerID int) error {
345 | 	if g.State != PlayerTurnState {
346 | 		return errors.New("cannot double down when not in player turn state")
347 | 	}
348 | 
349 | 	player := g.getPlayerByID(playerID)
350 | 	if player == nil {
351 | 		return errors.New("player not found")
352 | 	}
353 | 
354 | 	currentHand := g.getCurrentHand(player)
355 | 	if currentHand == nil {
356 | 		return errors.New("no active hand found")
357 | 	}
358 | 
359 | 	if !currentHand.CanDoubleDown(g.Rules) {
360 | 		return errors.New("cannot double down on this hand")
361 | 	}
362 | 
363 | 	// Double the bet
364 | 	player.Chips -= currentHand.Bet
365 | 	currentHand.Bet *= 2
366 | 	currentHand.IsDouble = true
367 | 
368 | 	// Give one more card
369 | 	card, err := g.Shoe.DrawCard()
370 | 	if err != nil {
371 | 		return err
372 | 	}
373 | 
374 | 	currentHand.Cards = append(currentHand.Cards, card)
375 | 
376 | 	// Check if the hand busted
377 | 	if currentHand.Value() > 21 {
378 | 		currentHand.IsBusted = true
379 | 	}
380 | 
381 | 	currentHand.Active = false
382 | 
383 | 	// Move to next hand or next player
384 | 	if !g.moveToNextHand() {
385 | 		g.moveToNextPlayer()
386 | 	}
387 | 
388 | 	return nil
389 | }
