482 | 	}
483 | 
484 | 	if player.Chips < amount {
485 | 		return errors.New("insufficient chips for insurance")
486 | 	}
487 | 
488 | 	// Process insurance bet (stored separately from main bet)
489 | 	// For now, we just acknowledge the bet was made
490 | 	// Actual resolution happens after dealer reveals hole card
491 | 
492 | 	return nil
493 | }
