495 | // LateSurrender allows a player to surrender after seeing dealer's upcard
496 | func (g *GameEngine) LateSurrender(playerID int) error {
497 | 	if !g.Rules.LateSurrender {
498 | 		return errors.New("late surrender not allowed with current rules")
499 | 	}
500 | 
501 | 	// Check if it's a valid time for surrender
502 | 	// (after initial deal but before taking any action)
503 | 	player := g.getPlayerByID(playerID)
504 | 	if player == nil {
505 | 		return errors.New("player not found")
506 | 	}
507 | 
508 | 	currentHand := g.getCurrentHand(player)
509 | 	if currentHand == nil {
510 | 		return errors.New("no active hand found")
511 | 	}
512 | 
513 | 	// Surrender: player loses half their bet
514 | 	player.Chips += currentHand.Bet / 2 // Return half the bet
515 | 	currentHand.Active = false
516 | 	currentHand.Bet = 0 // Mark as surrendered
517 | 
518 | 	// Move to next hand or next player
519 | 	if !g.moveToNextHand() {
520 | 		g.moveToNextPlayer()
521 | 	}
522 | 
523 | 	return nil
524 | }
