526 | // StartDealerTurn begins the dealer's turn
527 | func (g *GameEngine) StartDealerTurn() error {
528 | 	if g.State != PlayerTurnState {
529 | 		return errors.New("cannot start dealer turn when not in player turn state")
530 | 	}
531 | 
532 | 	// Check if there are any non-busted players
533 | 	if g.anyActivePlayers() {
534 | 		g.State = DealerTurnState
535 | 		g.playDealerTurn()
536 | 	}
537 | 
538 | 	return nil
