541 | // playDealerTurn implements the dealer's fixed strategy
542 | func (g *GameEngine) playDealerTurn() {
543 | 	// Dealer reveals hole card
544 | 	// The dealer's hole card is already in the hand, so no action needed here
545 | 
546 | 	// Dealer plays according to fixed rules
547 | 	for {
548 | 		value := g.Dealer.Value()
549 | 
550 | 		// Dealer hits on soft 17 if configured, otherwise stands on hard 17+
551 | 		if value < 17 || (value == 17 && g.Rules.DealerHitsSoft17 && g.Dealer.IsSoft()) {
552 | 			card, err := g.Shoe.DrawCard()
553 | 			if err != nil {
554 | 				break // No more cards
555 | 			}
556 | 			g.Dealer.Cards = append(g.Dealer.Cards, card)
557 | 
558 | 			if g.Dealer.Value() > 21 {
559 | 				g.Dealer.IsBusted = true
560 | 				break
561 | 			}
562 | 		} else {
563 | 			break // Dealer stands
564 | 		}
565 | 	}
566 | 
567 | 	g.State = EndRoundState
568 | }
569 | 
570 | // ResolveRound resolves all player hands against the dealer
571 | func (g *GameEngine) ResolveRound() error {
572 | 	if g.State != EndRoundState {
573 | 		return errors.New("round not ready to be resolved")
574 | 	}
575 | 
576 | 	for _, player := range g.Players {
577 | 		for _, hand := range player.Hands {
578 | 			result := g.calculateHandResult(hand)
579 | 
580 | 			switch result {
581 | 			case "win":
582 | 				player.Chips += hand.Bet * 2 // Original bet back plus winnings
583 | 			case "lose":
584 | 				// Player loses their bet (already deducted)
585 | 			case "push":
586 | 				player.Chips += hand.Bet // Return original bet
587 | 			case "blackjack":
588 | 				payout := math.Round(hand.Bet*g.Rules.BlackjackPayout*100) / 100 // Round to 2 decimal places
589 | 				player.Chips += hand.Bet + payout
590 | 			}
591 | 		}
592 | 
593 | 		// Reset player hands for next round
594 | 		player.Hands = make([]*Hand, 0)
595 | 		player.CurrentBet = 0
596 | 	}
597 | 
598 | 	// Reset dealer hand
599 | 	g.Dealer = &Hand{Cards: make([]cards.Card, 0)}
600 | 
601 | 	g.State = BettingState
602 | 
603 | 	return nil
604 | }
605 | 
606 | // calculateHandResult determines the outcome of a player hand vs dealer
607 | func (g *GameEngine) calculateHandResult(hand *Hand) string {
608 | 	playerValue := hand.Value()
609 | 	dealerValue := g.Dealer.Value()
610 | 
611 | 	// If player busted, they lose regardless of dealer
612 | 	if hand.IsBusted {
613 | 		return "lose"
614 | 	}
615 | 
616 | 	// If dealer busted and player didn't, player wins
617 | 	if g.Dealer.IsBusted {
618 | 		return "win"
619 | 	}
620 | 
621 | 	// Natural blackjack pays differently
622 | 	if hand.IsBlackjack {
623 | 		// If dealer also has blackjack, it's a push
624 | 		if g.Dealer.IsBlackjack {
625 | 			return "push"
626 | 		}
627 | 		return "blackjack"
628 | 	}
629 | 
630 | 	// Regular comparison
631 | 	if playerValue > dealerValue {
632 | 		return "win"
633 | 	} else if playerValue < dealerValue {
634 | 		return "lose"
635 | 	} else {
636 | 		return "push" // Tie
637 | 	}
638 | }
