640 | // moveToNextHand moves to the next active hand for the current player
641 | // Returns true if moved to next hand, false if no more hands
642 | func (g *GameEngine) moveToNextHand() bool {
643 | 	player := g.Players[g.CurrentPlayerIndex]
644 | 
645 | 	// Find next active hand
646 | 	for i := g.CurrentHandIndex + 1; i < len(player.Hands); i++ {
647 | 		if player.Hands[i].Active {
648 | 			g.CurrentHandIndex = i
649 | 			return true
650 | 		}
651 | 	}
652 | 
653 | 	return false
654 | }
655 | 
656 | // moveToNextPlayer moves to the next player with active hands
657 | func (g *GameEngine) moveToNextPlayer() {
658 | 	// Find next player with active hands
659 | 	for i := g.CurrentPlayerIndex + 1; i < len(g.Players); i++ {
660 | 		player := g.Players[i]
661 | 		for _, hand := range player.Hands {
662 | 			if hand.Active {
663 | 				g.CurrentPlayerIndex = i
664 | 				g.CurrentHandIndex = 0
665 | 				// Find the first active hand for this player
666 | 				for j, h := range player.Hands {
667 | 					if h.Active {
668 | 						g.CurrentHandIndex = j
669 | 						return
670 | 					}
671 | 				}
672 | 				break
673 | 			}
674 | 		}
675 | 	}
676 | 
677 | 	// If no more players with active hands, move to dealer turn
678 | 	if !g.anyActivePlayers() {
679 | 		g.StartDealerTurn()
680 | 	}
681 | }
