683 | // anyActivePlayers checks if any player has any active hands
684 | func (g *GameEngine) anyActivePlayers() bool {
685 | 	for _, player := range g.Players {
686 | 		for _, hand := range player.Hands {
687 | 			if hand.Active {
688 | 				return true
689 | 			}
690 | 		}
691 | 	}
692 | 	return false
693 | }
