package ui

import (
	"fmt"
	"strings"

	"blackjack/pkg/cards"
)

// PrintCard prints an ASCII representation of a single card
func PrintCard(card cards.Card) string {
	var top, middle, bottom string

	// Define the card borders
	top = "┌─────────┐"
	bottom = "└─────────┘"

	// Format the card content
	contentTop := fmt.Sprintf("%-2s", card.Rank)
	contentBottom := fmt.Sprintf("%2s", card.Rank)

	// Center the suit symbol
	suitLine := fmt.Sprintf(" %s ", card.Suit)

	middle = fmt.Sprintf("│%s       │\n│    %s    │\n│       %s│", contentTop, suitLine, contentBottom)

	return fmt.Sprintf("%s\n%s\n%s", top, middle, bottom)
}

// PrintHiddenCard prints an ASCII representation of a hidden/back card
func PrintHiddenCard() string {
	top := "┌─────────┐"
	middle := "│░░░░░░░░░│\n│░░░░░░░░░│\n│░░░░░░░░░│"
	bottom := "└─────────┘"

	return fmt.Sprintf("%s\n%s\n%s", top, middle, bottom)
}

// PrintHand prints multiple cards horizontally side by side
func PrintHand(hand []cards.Card, hideFirst bool) string {
	if len(hand) == 0 {
		return ""
	}

	// Create slices to hold each row of all cards
	var rows []string

	// Get the ASCII representation of each card
	cardStrings := make([][]string, len(hand))
	for i, card := range hand {
		var cardStr string
		if i == 0 && hideFirst {
			cardStr = PrintHiddenCard()
		} else {
			cardStr = PrintCard(card)
		}
		cardStrings[i] = strings.Split(cardStr, "\n")
	}

	// Combine the rows
	for rowIndex := 0; rowIndex < len(cardStrings[0]); rowIndex++ {
		var rowBuilder strings.Builder
		for cardIndex, cardRows := range cardStrings {
			rowBuilder.WriteString(cardRows[rowIndex])
			if cardIndex < len(cardStrings)-1 {
				rowBuilder.WriteString(" ") // Space between cards
			}
		}
		rows = append(rows, rowBuilder.String())
	}

	return strings.Join(rows, "\n")
}

// PrintCenteredText centers text within a specified width
func PrintCenteredText(text string, width int) string {
	textLen := len(text)
	if textLen >= width {
		return text
	}

	padding := (width - textLen) / 2
	return fmt.Sprintf("%s%s%s", strings.Repeat(" ", padding), text, strings.Repeat(" ", width-padding-textLen))
}

// PrintBox creates a bordered box with content
func PrintBox(content string, width int) string {
	lines := strings.Split(content, "\n")
	var result strings.Builder

	// Top border
	result.WriteString("┌" + strings.Repeat("─", width-2) + "┐\n")

	// Content with side borders
	for _, line := range lines {
		if len(line) > width-4 {
			line = line[:width-4] // Truncate if too long
		}
		result.WriteString(fmt.Sprintf("│ %s%s │\n", line, strings.Repeat(" ", width-4-len(line))))
	}

	// Bottom border
	result.WriteString("└" + strings.Repeat("─", width-2) + "┘")

	return result.String()
}

// PrintMenu prints a formatted menu
func PrintMenu(title string, options []string) string {
	var result strings.Builder

	result.WriteString(PrintCenteredText(title, 50) + "\n")
	result.WriteString(strings.Repeat("=", 50) + "\n")

	for i, option := range options {
		result.WriteString(fmt.Sprintf("%d. %s\n", i+1, option))
	}

	return result.String()
}

// PrintStatus displays the current game status
func PrintStatus(dealerHand []cards.Card, playerHand []cards.Card, playerName string, bet float64, isDealerTurn bool) string {
	var result strings.Builder

	result.WriteString("\n" + strings.Repeat("=", 60) + "\n")
	result.WriteString(PrintCenteredText("BLACKJACK TABLE", 60) + "\n")
	result.WriteString(strings.Repeat("=", 60) + "\n\n")

	// Dealer section
	result.WriteString("DEALER:\n")
	if isDealerTurn {
		result.WriteString(PrintHand(dealerHand, false)) // Show all cards during dealer's turn
	} else {
		result.WriteString(PrintHand(dealerHand, true)) // Hide first card initially
	}
	result.WriteString("\n\n")

	// Player section
	result.WriteString(fmt.Sprintf("%s (Bet: %.2f):\n", playerName, bet))
	result.WriteString(PrintHand(playerHand, false))
	result.WriteString("\n\n")

	return result.String()
}

// ClearScreen attempts to clear the terminal screen
func ClearScreen() {
	fmt.Print("\033[2J\033[H") // ANSI escape codes to clear screen and move cursor to top-left
}

package oracle

import (
	"blackjack/pkg/cards"
)

// CountSystem represents different card counting systems
type CountSystem string

const (
	HiLoCount   CountSystem = "hi-lo"
	KOCount     CountSystem = "ko"
	OmegaIICount CountSystem = "omega-ii"
)

// CardCounter tracks the running count and calculates true count
type CardCounter struct {
	System       CountSystem
	RunningCount float64
	DecksUsed    float64
	TotalDecks   int
	DeckPenetration float64 // How much of the shoe has been dealt (0.0 to 1.0)
}

// NewCardCounter creates a new card counter with the specified system
func NewCardCounter(system CountSystem, totalDecks int) *CardCounter {
	return &CardCounter{
		System:       system,
		RunningCount: 0,
		DecksUsed:    0,
		TotalDecks:   totalDecks,
		DeckPenetration: 0,
	}
}

// UpdateCount updates the running count based on the card played
func (cc *CardCounter) UpdateCount(card cards.Card) {
	switch cc.System {
	case HiLoCount:
		cc.runningCountHiLo(card)
	case KOCount:
		cc.runningCountKO(card)
	case OmegaIICount:
		cc.runningCountOmegaII(card)
	}
}

// runningCountHiLo updates the running count using the Hi-Lo system
// 2-6: +1, 7-9: 0, 10-A: -1
func (cc *CardCounter) runningCountHiLo(card cards.Card) {
	switch card.Rank {
	case cards.Two, cards.Three, cards.Four, cards.Five, cards.Six:
		cc.RunningCount++
	case cards.Ten, cards.Jack, cards.Queen, cards.King, cards.Ace:
		cc.RunningCount--
	// 7, 8, 9 have no effect on Hi-Lo count
	}
}

// runningCountKO updates the running count using the KO system
// 2-7: +1, 8-9: 0, 10-A: -1
func (cc *CardCounter) runningCountKO(card cards.Card) {
	switch card.Rank {
	case cards.Two, cards.Three, cards.Four, cards.Five, cards.Six, cards.Seven:
		cc.RunningCount++
	case cards.Ten, cards.Jack, cards.Queen, cards.King, cards.Ace:
		cc.RunningCount--
	// 8, 9 have no effect on KO count
	}
}

// runningCountOmegaII updates the running count using the Omega II system
// 4, 5, 6: +2, 3, 7: +1, 8: 0, 2, 9: -1, 10-A: -2
func (cc *CardCounter) runningCountOmegaII(card cards.Card) {
	switch card.Rank {
	case cards.Four, cards.Five, cards.Six:
		cc.RunningCount += 2
	case cards.Three, cards.Seven:
		cc.RunningCount++
	case cards.Eight:
		// No change
	case cards.Two, cards.Nine:
		cc.RunningCount--
	case cards.Ten, cards.Jack, cards.Queen, cards.King, cards.Ace:
		cc.RunningCount -= 2
	}
}

// UpdateDecksPlayed updates the number of decks played and penetration
func (cc *CardCounter) UpdateDecksPlayed(cardsPlayed int) {
	// Each deck has 52 cards
	cc.DecksUsed = float64(cardsPlayed) / 52.0
	cc.DeckPenetration = cc.DecksUsed / float64(cc.TotalDecks)
}

// TrueCount calculates the true count based on the running count and remaining decks
func (cc *CardCounter) TrueCount() float64 {
	remainingDecks := float64(cc.TotalDecks) - cc.DecksUsed

	if remainingDecks <= 0 {
		return cc.RunningCount
	}

	return cc.RunningCount / remainingDecks
}

// BetRecommendation suggests a bet multiplier based on the true count
func (cc *CardCounter) BetRecommendation(baseBet float64) float64 {
	trueCount := cc.TrueCount()

	// Basic betting strategy: increase bet with higher true count
	// This is a simplified version - real systems are more complex
	if trueCount <= 0 {
		return baseBet // Bet minimum or base amount
	}

	// Scale bet proportionally to true count (can be adjusted)
	scaleFactor := trueCount
	if scaleFactor > 5 {
		scaleFactor = 5 // Cap the bet multiplier
	}

	return baseBet * scaleFactor
}

// PenetrationPercentage returns how much of the shoe has been dealt
func (cc *CardCounter) PenetrationPercentage() float64 {
	return cc.DeckPenetration * 100
}

// Reset resets the counter to initial state
func (cc *CardCounter) Reset(totalDecks int) {
	cc.RunningCount = 0
	cc.DecksUsed = 0
	cc.TotalDecks = totalDecks
	cc.DeckPenetration = 0
}

// GetCountInfo returns a summary of the current count information
func (cc *CardCounter) GetCountInfo() map[string]interface{} {
	return map[string]interface{}{
		"system":              cc.System,
		"running_count":       cc.RunningCount,
		"true_count":          cc.TrueCount(),
		"decks_used":          cc.DecksUsed,
		"total_decks":         cc.TotalDecks,
		"penetration_percent": cc.PenetrationPercentage(),
	}
}

package oracle

import (
	"blackjack/internal/game"
	"blackjack/pkg/cards"
)

// Action represents a possible player action
type Action string

const (
	HitAction     Action = "hit"
	StandAction   Action = "stand"
	DoubleAction  Action = "double"
	SplitAction   Action = "split"
	SurrenderAction Action = "surrender"
)

// StrategyAdvisor provides optimal play recommendations based on card counting and basic strategy
type StrategyAdvisor struct {
	RuleSet *game.RuleSet
	Counter *CardCounter
}

// NewStrategyAdvisor creates a new strategy advisor with the specified rules and counting system
func NewStrategyAdvisor(ruleSet *game.RuleSet, counter *CardCounter) *StrategyAdvisor {
	return &StrategyAdvisor{
		RuleSet: ruleSet,
		Counter: counter,
	}
}

// GetRecommendedAction returns the optimal action based on player hand, dealer upcard, and true count
func (sa *StrategyAdvisor) GetRecommendedAction(playerHand []cards.Card, dealerUpcard cards.Card, currentBet float64) Action {
	playerSum := sa.getHandValue(playerHand)
	dealerValue := sa.getCardValue(dealerUpcard)

	// Determine if player hand is soft (contains ace counted as 11)
	isSoft := sa.isSoftHand(playerHand)

	// If hand is a pair, check for split opportunities first
	if len(playerHand) == 2 && playerHand[0].Rank == playerHand[1].Rank {
		action := sa.checkPairStrategy(playerHand[0].Rank, dealerValue, isSoft)
		if action != "" {
			return action
		}
	}

	// Determine action based on hand type
	if isSoft {
		return sa.getSoftHandStrategy(playerSum, dealerValue)
	} else {
		return sa.getHardHandStrategy(playerSum, dealerValue)
	}
}

// getHandValue calculates the value of a hand, preferring the highest value <= 21
func (sa *StrategyAdvisor) getHandValue(hand []cards.Card) int {
	value := 0
	aces := 0

	for _, card := range hand {
		if card.Rank == cards.Ace {
			aces++
			value += 11
		} else {
			value += sa.getCardValue(card)
		}
	}

	// Adjust for aces if value exceeds 21
	for aces > 0 && value > 21 {
		value -= 10 // Change ace from 11 to 1
		aces--
	}

	return value
}

// getCardValue returns the numeric value of a card
func (sa *StrategyAdvisor) getCardValue(card cards.Card) int {
	return card.Value
}

// isSoftHand returns true if the hand contains an ace counted as 11
func (sa *StrategyAdvisor) isSoftHand(hand []cards.Card) bool {
	valueWithoutAceAdjustment := 0
	hasAce := false

	for _, card := range hand {
		if card.Rank == cards.Ace {
			hasAce = true
			valueWithoutAceAdjustment += 11
		} else {
			valueWithoutAceAdjustment += sa.getCardValue(card)
		}
	}

	// If the value without adjustment is <= 21 and has an ace, it's soft
	originalValue := valueWithoutAceAdjustment
	acesCount := 0
	for _, card := range hand {
		if card.Rank == cards.Ace {
			acesCount++
		}
	}

	// Check if after ace adjustments it's still soft
	valueWithAceAdjustment := sa.getHandValue(hand)

	// If original value <= 21 and we had to adjust aces, it's soft
	// Or if the value is less than original due to ace adjustments
	return hasAce && valueWithAceAdjustment <= 21 && valueWithAceAdjustment != originalValue
}

// checkPairStrategy returns the recommended action for a pair
func (sa *StrategyAdvisor) checkPairStrategy(rank cards.Rank, dealerValue int, isSoft bool) Action {
	// Convert dealer value to proper representation (11 for Ace)
	if dealerValue == 11 && rank == cards.Ace {
		// Special case for pair of aces
		return SplitAction
	}

	// Basic pair strategy based on rank and dealer upcard
	switch rank {
	case cards.Ace:
		return SplitAction // Always split aces
	case cards.Eight:
		return SplitAction // Always split eights
	case cards.Ten:
		return StandAction // Never split tens
	case cards.Nine:
		// Split 9-9 against dealer 2-6, 8-9; Stand against 7, 10, A
		if dealerValue >= 2 && dealerValue <= 6 || dealerValue == 8 || dealerValue == 9 {
			return SplitAction
		} else if dealerValue == 7 || dealerValue == 10 || dealerValue == 11 {
			return StandAction
		}
	case cards.Seven:
		// Split 7-7 against dealer 2-7; Hit against 8-A
		if dealerValue >= 2 && dealerValue <= 7 {
			return SplitAction
		} else {
			return HitAction
		}
	case cards.Six:
		// Split 6-6 against dealer 2-6; Hit against 7-A
		if dealerValue >= 2 && dealerValue <= 6 {
			return SplitAction
		} else {
			return HitAction
		}
	case cards.Five:
		// Treat as hard 10
		return sa.getHardHandStrategy(10, dealerValue)
	case cards.Four:
		// Split 4-4 against dealer 5-6 only (if DAS allowed)
		if sa.RuleSet.DoubleAfterSplit && dealerValue == 5 || dealerValue == 6 {
			return SplitAction
		} else {
			return HitAction
		}
	case cards.Three, cards.Two:
		// Split 2-2, 3-3 against dealer 2-7; Hit against 8-A
		if dealerValue >= 2 && dealerValue <= 7 {
			return SplitAction
		} else {
			return HitAction
		}
	}

	// Default: don't split
	return ""
}

// getSoftHandStrategy returns the recommended action for a soft hand
func (sa *StrategyAdvisor) getSoftHandStrategy(playerSum int, dealerValue int) Action {
	// Basic soft hand strategy
	switch playerSum {
	case 20: // A-9
		return StandAction
	case 19: // A-8
		// Stand, except double against dealer 6 (if allowed and only first 2 cards)
		if dealerValue == 6 {
			return DoubleAction
		}
		return StandAction
	case 18: // A-7
		if dealerValue == 2 || dealerValue == 7 || dealerValue == 8 {
			return StandAction
		} else if dealerValue >= 3 && dealerValue <= 6 {
			// Double if allowed, otherwise stand
			return DoubleAction
		} else {
			return HitAction
		}
	case 17: // A-6
		if dealerValue >= 3 && dealerValue <= 6 {
			// Double if allowed, otherwise hit
			return DoubleAction
		} else {
			return HitAction
		}
	case 16, 15: // A-5, A-4
		if dealerValue >= 4 && dealerValue <= 6 {
			// Double if allowed, otherwise hit
			return DoubleAction
		} else {
			return HitAction
		}
	case 14, 13: // A-3, A-2
		if dealerValue == 5 || dealerValue == 6 {
			// Double if allowed, otherwise hit
			return DoubleAction
		} else {
			return HitAction
		}
	default:
		return HitAction
	}
}

// getHardHandStrategy returns the recommended action for a hard hand
func (sa *StrategyAdvisor) getHardHandStrategy(playerSum int, dealerValue int) Action {
	// Basic hard hand strategy
	if playerSum >= 17 {
		return StandAction
	} else if playerSum >= 13 {
		if dealerValue >= 2 && dealerValue <= 6 {
			return StandAction
		} else {
			return HitAction
		}
	} else if playerSum == 12 {
		if dealerValue >= 4 && dealerValue <= 6 {
			return StandAction
		} else {
			return HitAction
		}
	} else if playerSum == 11 {
		// Always double if allowed, otherwise hit
		return DoubleAction
	} else if playerSum == 10 {
		if dealerValue >= 2 && dealerValue <= 9 {
			// Double if allowed, otherwise hit
			return DoubleAction
		} else {
			return HitAction
		}
	} else if playerSum == 9 {
		if dealerValue >= 3 && dealerValue <= 6 {
			// Double if allowed, otherwise hit
			return DoubleAction
		} else {
			return HitAction
		}
	} else {
		// Hands 4-8 should always hit
		return HitAction
	}
}

// GetAdvancedAction returns the optimal action with card counting adjustments
func (sa *StrategyAdvisor) GetAdvancedAction(playerHand []cards.Card, dealerUpcard cards.Card, currentBet float64) Action {
	// Get the basic strategy action first
	basicAction := sa.GetRecommendedAction(playerHand, dealerUpcard, currentBet)

	// Apply card counting adjustments
	trueCount := sa.Counter.TrueCount()

	// Adjust based on true count deviations from basic strategy
	playerSum := sa.getHandValue(playerHand)
	dealerValue := sa.getCardValue(dealerUpcard)

	// Specific index plays based on true count
	switch {
	case playerSum == 16 && dealerValue == 10:
		// 16 vs 10: Stand at TC >= 0, Hit at TC < 0
		if trueCount >= 0 && basicAction == HitAction {
			return StandAction
		}
	case playerSum == 15 && dealerValue == 10:
		// 15 vs 10: Stand at TC >= 4, Hit at TC < 4
		if trueCount >= 4 && basicAction == HitAction {
			return StandAction
		}
	case playerSum == 10 && dealerValue == 10:
		// 10 vs 10: Double at TC >= 4, otherwise hit
		if trueCount >= 4 && basicAction != DoubleAction {
			return DoubleAction
		}
	case playerSum == 12 && dealerValue >= 4 && dealerValue <= 6:
		// 12 vs 4,5,6: Stand at higher TC
		if (dealerValue == 4 && trueCount >= 5) ||
		   (dealerValue == 5 && trueCount >= 3) ||
		   (dealerValue == 6 && trueCount >= 2) {
			return StandAction
		}
	case playerSum == 13 && dealerValue == 2:
		// 13 vs 2: Stand at TC <= -2
		if trueCount <= -2 && basicAction == StandAction {
			return HitAction
		}
	case playerSum == 13 && dealerValue == 3:
		// 13 vs 3: Stand at TC <= -1
		if trueCount <= -1 && basicAction == StandAction {
			return HitAction
		}
	}

	// For pair splitting adjustments
	if len(playerHand) == 2 && playerHand[0].Rank == playerHand[1].Rank {
		rank := playerHand[0].Rank
		switch {
		case rank == cards.Nine && dealerValue == 7:
			// 9-9 vs 7: Stand at TC >= 4, Split otherwise
			if trueCount >= 4 {
				return StandAction
			}
		case rank == cards.Hero && dealerValue == 4: // Actually tens
			// 10-10 vs 5: Double at TC >= 5 (if allowed)
			if trueCount >= 5 && sa.RuleSet.DoubleAfterSplit {
				return DoubleAction
			}
		case rank == cards.Eight && dealerValue == 6:
			// 8-8 vs 6: Stand at very high TC (rare)
		}
	}

	return basicAction
}

// ShouldTakeInsurance returns whether the player should take insurance
func (sa *StrategyAdvisor) ShouldTakeInsurance(dealerUpcard cards.Card, currentBet float64) bool {
	if dealerUpcard.Rank != cards.Ace {
		return false // Insurance only available when dealer shows Ace
	}

	// In a neutral or negative count, insurance is generally not favorable
	// In a positive count rich in 10s, insurance becomes more favorable
	trueCount := sa.Counter.TrueCount()

	// Insurance becomes favorable when true count is significantly positive
	// This is typically when TC >= 3 for Hi-Lo, but varies by system
	switch sa.Counter.System {
	case HiLoCount:
		return trueCount >= 3
	case KOCount:
		return trueCount >= 3
	case OmegaIICount:
		return trueCount >= 2
	default:
		return false
	}
}

// ShouldSurrender returns whether the player should surrender
func (sa *StrategyAdvisor) ShouldSurrender(playerHand []cards.Card, dealerUpcard cards.Card) bool {
	if !sa.RuleSet.LateSurrender {
		return false // Surrender not allowed
	}

	playerSum := sa.getHandValue(playerHand)
	dealerValue := sa.getCardValue(dealerUpcard)

	// Basic surrender strategy
	switch {
	case playerSum == 16 && (dealerValue == 9 || dealerValue == 10 || dealerValue == 11):
		return true
	case playerSum == 15 && dealerValue == 10:
		return true
	default:
		return false
	}
}

package simulation

import (
	"math/rand"
	"sync"
	"time"

	"blackjack/internal/game"
	"blackjack/internal/oracle"
	"blackjack/pkg/cards"
)

// SimulationResult holds the results of a simulation run
type SimulationResult struct {
	TotalHands        int
	PlayerWins        int
	DealerWins        int
	Pushes            int
	PlayerBlackjacks  int
	NetProfit         float64
	ExpectedValue     float64
	HouseEdge         float64
	AvgBetSize        float64
	StdDeviation      float64
	WinRate           float64
}

// Simulator runs Monte Carlo simulations of blackjack games
type Simulator struct {
	RuleSet *game.RuleSet
	Runs    int
	BaseBet float64
	UseBasicStrategy bool
	UseCardCounting  bool
	CountSystem      oracle.CountSystem
	TrueCountCutoff  float64 // Minimum true count to deviate from basic strategy
}

// NewSimulator creates a new simulator with the specified parameters
func NewSimulator(ruleSet *game.RuleSet, runs int, baseBet float64) *Simulator {
	return &Simulator{
		RuleSet:          ruleSet,
		Runs:             runs,
		BaseBet:          baseBet,
		UseBasicStrategy: true,
		UseCardCounting:  false,
		CountSystem:      oracle.HiLoCount,
		TrueCountCutoff:  2.0,
	}
}

// EnableCardCounting enables card counting in the simulation
func (s *Simulator) EnableCardCounting(countSystem oracle.CountSystem, cutoff float64) {
	s.UseCardCounting = true
	s.CountSystem = countSystem
	s.TrueCountCutoff = cutoff
}

// DisableBasicStrategy disables basic strategy (plays randomly)
func (s *Simulator) DisableBasicStrategy() {
	s.UseBasicStrategy = false
}

// Run executes the simulation with the specified number of runs
func (s *Simulator) Run() *SimulationResult {
	// For better performance with large numbers of runs, we'll use goroutines
	// Split the total runs across multiple workers
	numWorkers := 4
	runsPerWorker := s.Runs / numWorkers

	var wg sync.WaitGroup
	resultsChan := make(chan *SimulationResult, numWorkers)

	startTime := time.Now()

	// Launch worker goroutines
	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			workerResult := s.runWorker(runsPerWorker)
			resultsChan <- workerResult
		}(i)
	}

	// Close the results channel when all workers are done
	go func() {
		wg.Wait()
		close(resultsChan)
	}()

	// Collect results from all workers
	finalResult := &SimulationResult{}
	for workerResult := range resultsChan {
		finalResult.TotalHands += workerResult.TotalHands
		finalResult.PlayerWins += workerResult.PlayerWins
		finalResult.DealerWins += workerResult.DealerWins
		finalResult.Pushes += workerResult.Pushes
		finalResult.PlayerBlackjacks += workerResult.PlayerBlackjacks
		finalResult.NetProfit += workerResult.NetProfit
		finalResult.AvgBetSize += workerResult.AvgBetSize * float64(workerResult.TotalHands) // Weighted average
	}

	// Calculate weighted average bet size
	if finalResult.TotalHands > 0 {
		finalResult.AvgBetSize /= float64(finalResult.TotalHands)
	}

	// Calculate derived statistics
	finalResult.WinRate = float64(finalResult.PlayerWins) / float64(finalResult.TotalHands)
	finalResult.ExpectedValue = finalResult.NetProfit / float64(finalResult.TotalHands)
	finalResult.HouseEdge = -finalResult.ExpectedValue / finalResult.AvgBetSize

	duration := time.Since(startTime)
	_ = duration // For potential logging if needed

	return finalResult
}

// runWorker performs a portion of the total simulation runs
func (s *Simulator) runWorker(runs int) *SimulationResult {
	result := &SimulationResult{}

	// Initialize a new random seed for this worker to avoid correlation
	rand.Seed(time.Now().UnixNano() + int64(rand.Intn(10000)))

	for i := 0; i < runs; i++ {
		gameResult := s.simulateSingleGame()
		s.updateResult(result, gameResult)
	}

	return result
}

// simulateSingleGame simulates a single game of blackjack
func (s *Simulator) simulateSingleGame() *game.Hand {
	// Create a new game engine for this simulation
	engine := game.NewGameEngine(s.RuleSet)

	// Add a player
	playerID := 1
	engine.AddPlayer(playerID, "SimulatedPlayer", 1000.0) // Starting with 1000 chips

	// Place a bet
	bet := s.BaseBet
	_ = engine.PlaceBet(playerID, bet)

	// Deal initial cards
	_ = engine.DealInitialCards()

	// Check if there's a blackjack
	player := engine.Players[0]
	playerHand := player.Hands[0]

	// If there's a blackjack, the game is already resolved
	if playerHand.IsBlackjack {
		return playerHand
	}

	// Initialize card counter if needed
	var counter *oracle.CardCounter
	var advisor *oracle.StrategyAdvisor

	if s.UseCardCounting {
		counter = oracle.NewCardCounter(s.CountSystem, s.RuleSet.NumDecks)
		advisor = oracle.NewStrategyAdvisor(s.RuleSet, counter)

		// Count the initial cards dealt
		for _, p := range engine.Players {
			for _, h := range p.Hands {
				for _, c := range h.Cards {
					counter.UpdateCount(c)
				}
			}
		}
		for _, c := range engine.Dealer.Cards {
			counter.UpdateCount(c)
		}
	}

	// Player's turn
	for engine.State == game.PlayerTurnState {
		currentHand := engine.getCurrentHand(player)

		if !currentHand.Active {
			// Move to next hand or player if this hand is inactive
			if !engine.moveToNextHand() {
				engine.moveToNextPlayer()
			}
			continue
		}

		// Determine action based on strategy
		var action oracle.Action
		if s.UseBasicStrategy {
			dealerUpcard := engine.Dealer.Cards[0]

			if s.UseCardCounting && advisor != nil {
				action = advisor.GetAdvancedAction(currentHand.Cards, dealerUpcard, currentHand.Bet)
			} else if advisor != nil {
				action = advisor.GetRecommendedAction(currentHand.Cards, dealerUpcard, currentHand.Bet)
			} else {
				// Fallback to basic strategy without advisor
				action = s.getBasicStrategyAction(currentHand.Cards, engine.Dealer.Cards[0])
			}
		} else {
			// Random strategy
			actions, _ := engine.GetAvailableActions(playerID)
			if len(actions) > 0 {
				randomIndex := rand.Intn(len(actions))
				switch actions[randomIndex] {
				case "hit":
					action = oracle.HitAction
				case "stand":
					action = oracle.StandAction
				case "double":
					action = oracle.DoubleAction
				case "split":
					action = oracle.SplitAction
				case "surrender":
					action = oracle.SurrenderAction
				}
			}
		}

		// Execute the determined action
		switch action {
		case oracle.HitAction:
			_ = engine.Hit(playerID)
		case oracle.StandAction:
			_ = engine.Stand(playerID)
		case oracle.DoubleAction:
			if currentHand.CanDoubleDown(s.RuleSet) {
				_ = engine.DoubleDown(playerID)
			} else {
				_ = engine.Hit(playerID) // Fallback to hit if can't double
			}
		case oracle.SplitAction:
			if currentHand.CanSplit(s.RuleSet) {
				_ = engine.Split(playerID)
			} else {
				_ = engine.Hit(playerID) // Fallback to hit if can't split
			}
		case oracle.SurrenderAction:
			_ = engine.LateSurrender(playerID)
		default:
			_ = engine.Hit(playerID) // Default to hit
		}

		// Update counter if applicable
		if counter != nil && action != oracle.SurrenderAction {
			// Get the last card drawn (this is tricky in the engine, so we'll update based on the new state)
			// For simulation purposes, we'll assume the action was taken and update accordingly
		}
	}

	// If the state is still PlayerTurnState, move to dealer
	if engine.State == game.PlayerTurnState {
		engine.StartDealerTurn()
	}

	// Resolve the round
	_ = engine.ResolveRound()

	// Return the final player hand for analysis
	return playerHand
}

// getBasicStrategyAction returns the basic strategy action for a given hand
func (s *Simulator) getBasicStrategyAction(hand []cards.Card, dealerUpcard cards.Card) oracle.Action {
	playerSum := s.getHandValue(hand)
	dealerValue := s.getCardValue(dealerUpcard)

	// Check for pairs first
	if len(hand) == 2 && hand[0].Rank == hand[1].Rank {
		switch hand[0].Rank {
		case cards.Ace:
			return oracle.SplitAction
		case cards.Eight:
			return oracle.SplitAction
		case cards.Nine:
			if dealerValue == 7 || dealerValue >= 10 {
				return oracle.StandAction
			} else if dealerValue >= 2 && dealerValue <= 6 || dealerValue == 8 || dealerValue == 9 {
				return oracle.SplitAction
			}
		case cards.Six:
			if dealerValue >= 2 && dealerValue <= 6 {
				return oracle.SplitAction
			}
		case cards.Five:
			if dealerValue >= 2 && dealerValue <= 9 {
				return oracle.DoubleAction
			}
		case cards.Four:
			if dealerValue >= 5 && dealerValue <= 6 && s.RuleSet.DoubleAfterSplit {
				return oracle.SplitAction
			}
		case cards.Three, cards.Two:
			if dealerValue >= 2 && dealerValue <= 7 {
				return oracle.SplitAction
			}
		}
	}

	// Check for soft hands (hands with an ace counted as 11)
	if s.isSoftHand(hand) {
		switch playerSum {
		case 20: // A-9
			return oracle.StandAction
		case 19: // A-8
			if dealerValue == 6 {
				return oracle.DoubleAction
			}
			return oracle.StandAction
		case 18: // A-7
			if dealerValue >= 3 && dealerValue <= 6 {
				return oracle.DoubleAction
			} else if dealerValue == 2 || dealerValue == 7 || dealerValue == 8 {
				return oracle.StandAction
			}
		case 17: // A-6
			if dealerValue >= 3 && dealerValue <= 6 {
				return oracle.DoubleAction
			}
		case 16, 15: // A-5, A-4
			if dealerValue >= 4 && dealerValue <= 6 {
				return oracle.DoubleAction
			}
		case 14, 13: // A-3, A-2
			if dealerValue == 5 || dealerValue == 6 {
				return oracle.DoubleAction
			}
		}
		return oracle.HitAction
	}

	// Hard hands
	switch playerSum {
	case 20, 19, 18, 17:
		return oracle.StandAction
	case 16:
		if dealerValue >= 2 && dealerValue <= 6 {
			return oracle.StandAction
		}
	case 15:
		if dealerValue >= 2 && dealerValue <= 6 {
			return oracle.StandAction
		}
	case 14, 13:
		if dealerValue >= 2 && dealerValue <= 6 {
			return oracle.StandAction
		}
	case 12:
		if dealerValue >= 4 && dealerValue <= 6 {
			return oracle.StandAction
		}
	case 11:
		return oracle.DoubleAction
	case 10:
		if dealerValue >= 2 && dealerValue <= 9 {
			return oracle.DoubleAction
		}
	case 9:
		if dealerValue >= 3 && dealerValue <= 6 {
			return oracle.DoubleAction
		}
	}

	// Default to hit for low hands or if no other condition is met
	return oracle.HitAction
}

// getHandValue calculates the value of a hand, preferring the highest value <= 21
func (s *Simulator) getHandValue(hand []cards.Card) int {
	value := 0
	aces := 0

	for _, card := range hand {
		if card.Rank == cards.Ace {
			aces++
			value += 11
		} else {
			value += s.getCardValue(card)
		}
	}

	// Adjust for aces if value exceeds 21
	for aces > 0 && value > 21 {
		value -= 10 // Change ace from 11 to 1
		aces--
	}

	return value
}

// getCardValue returns the numeric value of a card
func (s *Simulator) getCardValue(card cards.Card) int {
	return card.Value
}

// isSoftHand returns true if the hand contains an ace counted as 11
func (s *Simulator) isSoftHand(hand []cards.Card) bool {
	valueWithoutAceAdjustment := 0
	hasAce := false

	for _, card := range hand {
		if card.Rank == cards.Ace {
			hasAce = true
			valueWithoutAceAdjustment += 11
		} else {
			valueWithoutAceAdjustment += s.getCardValue(card)
		}
	}

	// If the value without adjustment is <= 21 and has an ace, it's soft
	originalValue := valueWithoutAceAdjustment
	acesCount := 0
	for _, card := range hand {
		if card.Rank == cards.Ace {
			acesCount++
		}
	}

	// Check if after ace adjustments it's still soft
	valueWithAceAdjustment := s.getHandValue(hand)

	// If original value <= 21 and we had to adjust aces, it's soft
	// Or if the value is less than original due to ace adjustments
	return hasAce && valueWithAceAdjustment <= 21 && valueWithAceAdjustment != originalValue
}

// updateResult updates the cumulative result with a single game result
func (s *Simulator) updateResult(result *SimulationResult, gameResult *game.Hand) {
	result.TotalHands++

	// Note: In the simulation context, we'd need to track wins/losses differently
	// This is a simplified version - in a real implementation, we'd track the
	// outcomes from the engine.ResolveRound() process

	// For now, we'll just increment hands played
	// The actual win/loss tracking would happen in the game engine during resolution
	result.TotalHands++
}

// RunComparison runs simulations comparing different strategies
func (s *Simulator) RunComparison() map[string]*SimulationResult {
	results := make(map[string]*SimulationResult)

	// Run with basic strategy only
	s.UseCardCounting = false
	s.UseBasicStrategy = true
	results["basic_strategy"] = s.Run()

	// Run with card counting (Hi-Lo)
	s.EnableCardCounting(oracle.HiLoCount, 2.0)
	results["hi_lo_counting"] = s.Run()

	// Run with KO counting
	s.EnableCardCounting(oracle.KOCount, 2.0)
	results["ko_counting"] = s.Run()

	// Run with Omega II counting
	s.EnableCardCounting(oracle.OmegaIICount, 2.0)
	results["omega_ii_counting"] = s.Run()

	return results
}

