387 | 	if currentHand == nil {
388 | 		return errors.New("no active hand found")
389 | 	}
390 | 
391 | 	if !currentHand.CanSplit(g.Rules) {
392 | 		return errors.New("cannot split this hand")
393 | 	}
394 | 
395 | 	// Check if player has enough chips to split
396 | 	if player.Chips < currentHand.Bet {
397 | 		return errors.New("insufficient chips to split")
398 | 	}
399 | 
400 | 	// Deduct the additional bet amount
401 | 	player.Chips -= currentHand.Bet
402 | 
403 | 	// Split the hand
404 | 	cardToSplit := currentHand.Cards[1]
405 | 	currentHand.Cards = currentHand.Cards[:1] // Remove the second card
406 | 
407 | 	newHand := &Hand{
408 | 		Cards:   []cards.Card{cardToSplit},
409 | 		Bet:     currentHand.Bet,
410 | 		Active:  true,
411 | 		IsSplit: true,
412 | 	}
413 | 
414 | 	player.Hands = append(player.Hands, newHand)
415 | 
416 | 	// Draw a card for each hand
417 | 	card1, err := g.Shoe.DrawCard()
418 | 	if err != nil {
419 | 		return err
420 | 	}
421 | 	currentHand.Cards = append(currentHand.Cards, card1)
422 | 
423 | 	card2, err := g.Shoe.DrawCard()
424 | 	if err != nil {
425 | 		return err
426 | 	}
427 | 	newHand.Cards = append(newHand.Cards, card2)
428 | 
429 | 	// Check for blackjacks after split
430 | 	if g.hasBlackjack(currentHand) {
431 | 		currentHand.IsBlackjack = true
432 | 		currentHand.Active = false
433 | 	}
434 | 	if g.hasBlackjack(newHand) {
435 | 		newHand.IsBlackjack = true
436 | 		newHand.Active = false
437 | 	}
438 | 
439 | 	// If splitting aces, both hands get one card only
440 | 	if currentHand.Cards[0].Rank == cards.Ace && g.Rules.SplitAcesOnceOnly {
441 | 		currentHand.Active = false
442 | 		newHand.Active = false
443 | 	}
444 | 
445 | 	// Move to the next hand
446 | 	g.CurrentHandIndex++
447 | 
448 | 	return nil
449 | }
