451 | // Insurance handles an insurance bet
452 | func (g *GameEngine) Insurance(playerID int, amount float64) error {
453 | 	if !g.Rules.InsuranceAllowed {
454 | 		return errors.New("insurance not allowed with current rules")
455 | 	}
456 | 
457 | 	// Insurance is only offered when dealer's upcard is an Ace
458 | 	dealerUpcard := g.Dealer.Cards[0]
459 | 	if dealerUpcard.Rank != cards.Ace {
460 | 		return errors.New("insurance only available when dealer shows an Ace")
461 | 	}
