470 | 	}
471 | 
472 | 	// Process insurance bet (stored separately from main bet)
473 | 	// For now, we just acknowledge the bet was made
474 | 	// Actual resolution happens after dealer reveals hole card
475 | 
476 | 	return nil
477 | }
