479 | // LateSurrender allows a player to surrender after seeing dealer's upcard
480 | func (g *GameEngine) LateSurrender(playerID int) error {
481 | 	if !g.Rules.LateSurrender {
482 | 		return errors.New("late surrender not allowed with current rules")
483 | 	}
484 | 
485 | 	// Check if it's a valid time for surrender
486 | 	// (after initial deal but before taking any action)
487 | 	player := g.getPlayerByID(playerID)
488 | 	if player == nil {
489 | 		return errors.New("player not found")
490 | 	}
491 | 
492 | 	currentHand := g.getCurrentHand(player)
493 | 	if currentHand == nil {
494 | 		return errors.New("no active hand found")
495 | 	}
496 | 
497 | 	// Surrender: player loses half their bet
498 | 	player.Chips += currentHand.Bet / 2 // Return half the bet
499 | 	currentHand.Active = false
500 | 	currentHand.Bet = 0 // Mark as surrendered
501 | 
502 | 	// Move to next hand or next player
503 | 	if !g.moveToNextHand() {
504 | 		g.moveToNextPlayer()
505 | 	}
506 | 
507 | 	return nil
508 | }
