510 | // StartDealerTurn begins the dealer's turn
511 | func (g *GameEngine) StartDealerTurn() error {
512 | 	if g.State != PlayerTurnState {
513 | 		return errors.New("cannot start dealer turn when not in player turn state")
514 | 	}
515 | 
516 | 	// Check if there are any non-busted players
517 | 	if g.anyActivePlayers() {
518 | 		g.State = DealerTurnState
519 | 		g.playDealerTurn()
520 | 	}
521 | 
522 | 	return nil
523 | }
