525 | // playDealerTurn implements the dealer's fixed strategy
526 | func (g *GameEngine) playDealerTurn() {
527 | 	// Dealer reveals hole card
528 | 	// The dealer's hole card is already in the hand, so no action needed here
529 | 
530 | 	// Dealer plays according to fixed rules
531 | 	for {
532 | 		value := g.Dealer.Value()
533 | 
534 | 		// Dealer hits on soft 17 if configured, otherwise stands on hard 17+
535 | 		if value < 17 || (value == 17 && g.Rules.DealerHitsSoft17 && g.Dealer.IsSoft()) {
536 | 			card, err := g.Shoe.DrawCard()
537 | 			if err != nil {
538 | 				break // No more cards
539 | 			}
540 | 			g.Dealer.Cards = append(g.Dealer.Cards, card)
541 | 
542 | 			if g.Dealer.Value() > 21 {
543 | 				g.Dealer.IsBusted = true
544 | 				break
545 | 			}
546 | 		} else {
547 | 			break // Dealer stands
548 | 		}
549 | 	}
550 | 
551 | 	g.State = EndRoundState
552 | }
553 | 
554 | // ResolveRound resolves all player hands against the dealer
555 | func (g *GameEngine) ResolveRound() error {
556 | 	if g.State != EndRoundState {
557 | 		return errors.New("round not ready to be resolved")
558 | 	}
559 | 
560 | 	for _, player := range g.Players {
561 | 		for _, hand := range player.Hands {
562 | 			result := g.calculateHandResult(hand)
563 | 
564 | 			switch result {
565 | 			case "win":
566 | 				player.Chips += hand.Bet * 2 // Original bet back plus winnings (equal to bet amount)
567 | 			case "lose":
568 | 				// Player loses their bet (already deducted in PlaceBet)
569 | 			case "push":
570 | 				player.Chips += hand.Bet // Return original bet
571 | 			case "blackjack":
572 | 				payout := math.Round(hand.Bet*g.Rules.BlackjackPayout*100) / 100 // Round to 2 decimal places
573 | 				player.Chips += hand.Bet + payout                                // Original bet back plus payout
574 | 			}
575 | 		}
576 | 
577 | 		// Reset player hands for next round
578 | 		player.Hands = make([]*Hand, 0)
579 | 		player.CurrentBet = 0
580 | 	}
581 | 
582 | 	// Reset dealer hand
583 | 	g.Dealer = &Hand{Cards: make([]cards.Card, 0)}
584 | 
585 | 	g.State = BettingState
586 | 
587 | 	return nil
588 | }
589 | 
590 | // calculateHandResult determines the outcome of a player hand vs dealer
591 | func (g *GameEngine) calculateHandResult(hand *Hand) string {
592 | 	playerValue := hand.Value()
593 | 	dealerValue := g.Dealer.Value()
594 | 
595 | 	// If player busted, they lose regardless of dealer
596 | 	if hand.IsBusted {
597 | 		return "lose"
598 | 	}
599 | 
600 | 	// If dealer busted and player didn't, player wins
601 | 	if g.Dealer.IsBusted {
602 | 		return "win"
603 | 	}
604 | 
605 | 	// Natural blackjack pays differently
606 | 	if hand.IsBlackjack {
607 | 		// If dealer also has blackjack, it's a push
608 | 		if g.Dealer.IsBlackjack {
609 | 			return "push"
610 | 		}
611 | 		return "blackjack"
612 | 	}
613 | 
614 | 	// Regular comparison
615 | 	if playerValue > dealerValue {
616 | 		return "win"
617 | 	} else if playerValue < dealerValue {
618 | 		return "lose"
619 | 	} else {
620 | 		return "push" // Tie
621 | 	}
622 | }
