624 | // moveToNextHand moves to the next active hand for the current player
625 | // Returns true if moved to next hand, false if no more hands
626 | func (g *GameEngine) moveToNextHand() bool {
627 | 	player := g.Players[g.CurrentPlayerIndex]
628 | 
629 | 	// Find next active hand
