351 | 
352 | 			if s.getHandValue(dealerHand.Cards) > 21 {
353 | 				dealerHand.IsBusted = true
354 | 				break
355 | 			}
356 | 		} else {
357 | 			break // Dealer stands
358 | 		}
359 | 	}
