364 | // getBasicStrategyAction returns the basic strategy action for a given hand
365 | func (s *Simulator) getBasicStrategyAction(hand []cards.Card, dealerUpcard cards.Card) oracle.Action {
366 | 	playerSum := s.getHandValue(hand)
367 | 	dealerValue := s.getCardValue(dealerUpcard)
