420 | 				return oracle.DoubleAction
421 | 			}
422 | 			return oracle.HitAction
423 | 		case 16, 15: // A-5, A-4
424 | 			if dealerValue >= 4 && dealerValue <= 6 {
425 | 				return oracle.DoubleAction
426 | 			}
427 | 			return oracle.HitAction
428 | 		case 14, 13: // A-3, A-2
429 | 			if dealerValue == 5 || dealerValue == 6 {
430 | 				return oracle.DoubleAction
431 | 			}
432 | 			return oracle.HitAction
433 | 		}
434 | 		return oracle.HitAction
435 | 	}
436 | 
437 | 	// Hard hands
438 | 	switch playerSum {
439 | 	case 20, 19, 18, 17:
440 | 		return oracle.StandAction
441 | 	case 16:
442 | 		if dealerValue >= 2 && dealerValue <= 6 {
443 | 			return oracle.StandAction
444 | 		}
445 | 		return oracle.HitAction
446 | 	case 15:
447 | 		if dealerValue >= 2 && dealerValue <= 6 {
448 | 			return oracle.StandAction
449 | 		}
450 | 		return oracle.HitAction
451 | 	case 14, 13:
452 | 		if dealerValue >= 2 && dealerValue <= 6 {
453 | 			return oracle.StandAction
454 | 		}
455 | 		return oracle.HitAction
456 | 	case 12:
457 | 		if dealerValue >= 4 && dealerValue <= 6 {
458 | 			return oracle.StandAction
459 | 		}
460 | 		return oracle.HitAction
461 | 	case 11:
462 | 		return oracle.DoubleAction
463 | 	case 10:
464 | 		if dealerValue >= 2 && dealerValue <= 9 {
465 | 			return oracle.DoubleAction
466 | 		}
467 | 		return oracle.HitAction
468 | 	case 9:
469 | 		if dealerValue >= 3 && dealerValue <= 6 {
470 | 			return oracle.DoubleAction
471 | 		}
472 | 		return oracle.HitAction
473 | 	}
474 | 
475 | 	// Default to hit for low hands or if no other condition is met
476 | 	return oracle.HitAction
