538 | // isBlackjackHand checks if a hand is a blackjack (21 with an ace and a 10-value card)
539 | func (s *Simulator) isBlackjackHand(hand *game.Hand) bool {
540 | 	if len(hand.Cards) != 2 {
541 | 		return false
542 | 	}
543 | 
544 | 	card1, card2 := hand.Cards[0], hand.Cards[1]
545 | 
546 | 	// Check if one card is an ace and the other is a 10-value card
547 | 	isAceFirst := card1.Rank == cards.Ace
548 | 	isAceSecond := card2.Rank == cards.Ace
549 | 	isTenValuedFirst := card1.Value == 10
550 | 	isTenValuedSecond := card2.Value == 10
551 | 
552 | 	return (isAceFirst && isTenValuedSecond) || (isAceSecond && isTenValuedFirst)
