360 | 		return false // Surrender not allowed
361 | 	}
362 | 
363 | 	playerSum := sa.getHandValue(playerHand)
364 | 	dealerValue := sa.getCardValue(dealerUpcard)
365 | 
366 | 	// Basic surrender strategy
367 | 	switch {
368 | 	case playerSum == 16 && (dealerValue == 9 || dealerValue == 10 || dealerValue == 11):
369 | 		return true
370 | 	case playerSum == 15 && dealerValue == 10:
371 | 		return true
372 | 	default:
373 | 		return false
374 | 	}
